package com.communex.documents;import com.communex.users.User;import jakarta.persistence.*;import java.time.LocalDateTime;
@Entity @Table(name="user_documents",indexes=@Index(name="idx_user_documents_updated",columnList="user_id, updated_at"))public class UserDocument{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="user_id",nullable=false)private User user;@Column(nullable=false,length=160)private String title;@Column(nullable=false,columnDefinition="text")private String content="";@Column(nullable=false,updatable=false)private LocalDateTime createdAt;@Column(nullable=false)private LocalDateTime updatedAt;public UserDocument(){}@PrePersist public void create(){createdAt=LocalDateTime.now();updatedAt=createdAt;}@PreUpdate public void update(){updatedAt=LocalDateTime.now();}public Long getId(){return id;}public User getUser(){return user;}public void setUser(User v){user=v;}public String getTitle(){return title;}public void setTitle(String v){title=v;}public String getContent(){return content;}public void setContent(String v){content=v;}public LocalDateTime getCreatedAt(){return createdAt;}public LocalDateTime getUpdatedAt(){return updatedAt;}}
